def transform_v2(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    inner=[grid[r][c] for r in range(1,h-1) for c in range(1,w-1) if grid[r][c]!=bg]
    if not inner:return [row[:] for row in grid]
    fill=Counter(inner).most_common(1)[0][0]
    g=[row[:] for row in grid]
    def edge_runs(edge):
        vals = ([grid[0][c] for c in range(w)] if edge=='top' else
                [grid[h-1][c] for c in range(w)] if edge=='bottom' else
                [grid[r][0] for r in range(h)] if edge=='left' else
                [grid[r][w-1] for r in range(h)])
        runs=[];i=0
        while i<len(vals):
            if vals[i]==bg:i+=1;continue
            j=i+1
            while j<len(vals) and vals[j]==vals[i]:j+=1
            runs.append((vals[i],list(range(i,j))))
            i=j
        return runs
    pairs=[]
    for a,b in [('top','bottom'),('left','right')]:
        for col1,lanes1 in edge_runs(a):
            for col2,lanes2 in edge_runs(b):
                if col1==col2 and len(lanes1)==len(lanes2): pairs.append((a,b,lanes1,lanes2))
    for a,b,la,lb in pairs:
        active=set()
        for r in range(1,h-1):
            for c in range(1,w-1):
                if grid[r][c]==bg:continue
                pos=c if a in ('top','bottom') else r
                if pos in la:active.add(pos-la[0])
                if pos in lb:active.add(pos-lb[0])
        for edge,lanes in ((a,la),(b,lb)):
            for off in active:
                lane=lanes[off]
                if edge=='top':r,c,dr,dc=1,lane,1,0
                elif edge=='bottom':r,c,dr,dc=h-2,lane,-1,0
                elif edge=='left':r,c,dr,dc=lane,1,0,1
                else:r,c,dr,dc=lane,w-2,0,-1
                while 0<=r<h and 0<=c<w:
                    if grid[r][c]!=bg:
                        if grid[r][c]==fill:g[r][c]=4
                        break
                    g[r][c]=fill;r+=dr;c+=dc
    return g
